test("CAT-284: short pages from deleted records do not end the scan", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["i-1","i-3"]);
});
test("every collection honours pageSize and follows continuation bookmarks", () => {
  const gateway = new MemoryGateway({ projects: [{id:"1",name:"A",deleted:true},{id:"2",name:"B",deleted:true},{id:"3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "projects", {pageSize:2}).entries.map(r=>r.id), ["3"]);
  assert.deepEqual(gateway.requests.map(r=>[r.cursor,r.limit]), [[null,2],["2",2]]);
});
test("empty-string cursors are followed", () => {
  let calls = 0;
  const gateway = { fetch: (_c: string, cursor: string | null) => {
    calls++;
    return cursor === null ? { items: [], next: "" } : { items: [{id:"x",name:"X"}], next: null };
  } };
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:5}).entries.map(r=>r.id), ["x"]);
  assert.equal(calls, 2);
});
